# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">UNIT 4: ON THE PHONE — FOLLOWING PHONE CONVERSATIONS</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Introducing &amp; Asking for Someone</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Hello! This is Jack calling. Is Tom in?</text>\n  <text x="180" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Hi, Jane speaking. May I speak to Mr. Brown?</text>\n  <text x="180" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Could you put me through to the manager?</text>\n  <text x="180" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Is Sarah there? / Can I talk to Mert?</text>\n  <text x="180" y="200" text-anchor="middle" font-size="11" fill="#334155">Put someone through = Connect (Bağlamak)</text>\n  <text x="180" y="222" text-anchor="middle" font-size="11" fill="#2563eb">Extension 145 (Dahili hat 145) · Dial (Tuşlamak)</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Connecting, Waiting &amp; Leaving a Message</text>\n  <text x="520" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Hang on a minute; I\'ll get him / her.</text>\n  <text x="520" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Hold on a moment, please. Don\'t hang up.</text>\n  <text x="520" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• I\'m afraid he isn\'t available at the moment.</text>\n  <text x="520" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• He has gone out. / The line is engaged (busy).</text>\n  <text x="520" y="200" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">• Would you like to leave a message?</text>\n  <text x="520" y="222" text-anchor="middle" font-size="11" fill="#14532d">Take a memo (Not almak) · Leave a message (Mesaj bırakmak)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KEY PHONE VOCABULARY &amp; PHRASAL VERBS</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Essential Phrasal Verbs</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">• Pick up the phone: Telefonu açmak (cevaplamak)</text>\n  <text x="180" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">• Hang on / Hold on: Hatta beklemek (wait)</text>\n  <text x="180" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">• Hang up the phone: Telefonu kapatmak</text>\n  <text x="180" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">• Put someone through: Birini telefona bağlamak</text>\n  <text x="180" y="200" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">• Get back to someone: Birine geri dönüş yapmak</text>\n  <text x="180" y="224" text-anchor="middle" font-size="11" fill="#713f12">Get / Keep in touch: İletişim kurmak / İletişimde kalmak</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Communication Problemas &amp; Terms</text>\n  <text x="520" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Available = Free (Müsait, uygun)</text>\n  <text x="520" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Engaged = Busy = In use (Meşgul hat)</text>\n  <text x="520" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Bad line: Kötü hat / kesik ses (I can\'t hear you well)</text>\n  <text x="520" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Speak up, please: Lütfen daha yüksek sesle konuşun</text>\n  <text x="520" y="200" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Call center: Çağrı merkezi · Customer service</text>\n  <text x="520" y="224" text-anchor="middle" font-size="11" fill="#475569">Polite requests: Could you repeat that, please?</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">STATING DECISIONS TAKEN AT THE TIME OF SPEAKING (WILL)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Spontaneous Decisions with "will (\'ll)"</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">Subject + will (\'ll) + V1 (Base Verb)</text>\n  <text x="180" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#881337">• [The phone rings] — "I will take that!"</text>\n  <text x="180" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#881337">• "Hang on a minute; I\'ll get her."</text>\n  <text x="180" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#881337">• "I\'ll talk to you soon." / "I\'ll call back later."</text>\n  <text x="180" y="200" text-anchor="middle" font-size="12" font-weight="bold" fill="#881337">• "I\'ll get back to you in an hour."</text>\n  <text x="180" y="224" text-anchor="middle" font-size="11" fill="#9f1239">Konuşma anında verilen ani kararları ifade eder</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Arranging &amp; Changing Plans with "then"</text>\n  <text x="520" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• "I\'ll see you at the café tomorrow, then."</text>\n  <text x="520" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• "We\'ll meet next Saturday, then."</text>\n  <text x="520" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• "I\'m sorry to hear that. We\'ll meet up later, then."</text>\n  <text x="520" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• "I\'ll tell him that you called when he arrives."</text>\n  <text x="520" y="200" text-anchor="middle" font-size="12" font-weight="bold" fill="#164e63">• Negative: won\'t (will not) + V1</text>\n  <text x="520" y="224" text-anchor="middle" font-size="11" fill="#0f172a">"then" = o hâlde / öyleyse (konuşma anında varılan sonuç)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
